// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz: from address (as uint160), single-element tos array length controlled by tosAddrIsReverter
    function testFuzz_property(uint160 fromRaw, bool tosReverts) public {
        // keep from a non-zero address for realism
        address from = address(uint160(bound(fromRaw, 1, type(uint160).max)));

        // Deploy a helper that either reverts on transferFrom or records the call
        ReverterOrRecorder helper = new ReverterOrRecorder(tosReverts);

        // Build a single-element tos array (the contract expects address[] memory)
        address[] memory tos = new address[](1);
        tos[0] = address(helper);

        // We will call c.transfer and observe whether it reverts.
        // Reference contract: when helper reverts on the external call, C.transfer must revert.
        // Mutant: ignores the return value, so it will return true instead of reverting.

        bool ok;
        try c.transfer(from, address(helper), tos, 1) { ok = true; } catch { ok = false; }

        // Exact invariant: If the helper is configured to revert on the external call, then c.transfer MUST revert (ok == false).
        // This holds for the reference implementation for all inputs; the mutant (which drops require(_s)) will return true (ok == true) for some inputs and thus violate this assertion.
        if (tosReverts) {
            assertTrue(!ok);
        } else {
            // If helper does not revert, call should succeed in both reference and mutant; accept either outcome as long as it didn't revert.
            assertTrue(ok);
        }
    }
}

// Helper that can either revert on the expected transferFrom call, or record arguments and succeed.
contract ReverterOrRecorder {
    bool public shouldRevert;
    // recorded values when not reverting
    address public lastFrom;
    address public lastTo;
    uint public lastV;
    uint public calls;

    constructor(bool _shouldRevert) {
        shouldRevert = _shouldRevert;
    }

    // Match the selector bytes4(keccak256("transferFrom(address,address,uint256)")) so that c.call with that selector hits this function
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        if (shouldRevert) {
            revert("forced revert");
        }
        lastFrom = from;
        lastTo = to;
        lastV = v;
        calls += 1;
        return true;
    }
}
